function trunc(v, n) { const s = String(v == null ? '' : v); return s.length > n ? s.substring(0, n - 1) + '…' : s; }
function fmtCel(c) {
  if (c.tipo === 'formula') {
    const vc = (c.valorCache !== undefined && c.valorCache !== null && c.valorCache !== '') ? ('→' + trunc(c.valorCache, 24)) : '';
    return '[fórmula' + vc + ']';
  }
  const v = c.valor;
  if (c.tipo === 'numero' && Number.isInteger(Number(v)) && Number(v) >= 43000 && Number(v) <= 48500) {
    return v + '(data? ' + serialParaData(Number(v)) + ')';
  }
  return trunc(v, 46);
}
function renderPack(chave, buf) {
  const cfg = FIN_CONFIG[chave];
  const out = [];
  for (const aba of Object.keys(cfg.abas)) {
    const z = cfg.abas[aba];
    let cel = {};
    for (const rng of z.leitura) { try { Object.assign(cel, lerCelulas(buf, aba, [rng])); } catch (e) { out.push('## Aba "' + aba + '": ERRO DE LEITURA ' + e.message); } }
    out.push('## Aba "' + aba + '"' + (z.escrita.length ? ' — entrada permitida em: ' + z.escrita.join(', ') : ' — SOMENTE LEITURA'));
    if (z.append) {
      let pl = null;
      try { pl = primeiraLinhaVazia(buf, aba, z.append.col, z.append.ini, z.append.fim); } catch (e) {}
      out.push('>>> PRIMEIRA LINHA VAZIA para ' + z.append.label + ': ' + (pl === null ? 'NENHUMA (range cheio! avisar)' : pl));
    }
    const porLinha = {};
    for (const ref of Object.keys(cel)) {
      const c = cel[ref];
      if (!c || c.tipo === 'vazia') continue;
      const m = ref.match(/^([A-Z]+)([0-9]+)$/);
      if (!m) continue;
      const ln = parseInt(m[2], 10);
      (porLinha[ln] = porLinha[ln] || []).push({ col: m[1], txt: m[1] + '=' + fmtCel(c) });
    }
    for (const ln of Object.keys(porLinha).map(Number).sort((a, b) => a - b)) {
      const linha = porLinha[ln].sort((a, b) => colParaNumero(a.col) - colParaNumero(b.col)).map(x => x.txt).join(' | ');
      out.push('L' + ln + ': ' + linha);
    }
  }
  return out.join('\n');
}

