function refDentro(ranges, ref) {
  const m = String(ref).toUpperCase().match(/^([A-Z]+)([0-9]+)$/);
  if (!m) return false;
  const cn = colParaNumero(m[1]), ln = parseInt(m[2], 10);
  for (const r of ranges) {
    const [a, b] = r.includes(':') ? r.split(':') : [r, r];
    const pa = parseRef(a), pb = parseRef(b);
    if (cn >= Math.min(pa.colNum, pb.colNum) && cn <= Math.max(pa.colNum, pb.colNum) &&
        ln >= Math.min(pa.linha, pb.linha) && ln <= Math.max(pa.linha, pb.linha)) return true;
  }
  return false;
}

function serialParaData(v) {
  const ms = (v - 25569) * 86400000;
  const d = new Date(ms);
  const p = n => String(n).padStart(2, '0');
  return p(d.getUTCDate()) + '/' + p(d.getUTCMonth() + 1) + '/' + d.getUTCFullYear();
}

function validarPlano(plano, planilhas) {
  // whitelist dura + dry-run do patch (pega formula/shared-formula agora)
  if (!plano || typeof plano !== 'object') throw new Error('plano vazio');
  const chave = String(plano.chave || '');
  const cfg = FIN_CONFIG[chave];
  if (!cfg) throw new Error('arquivo desconhecido: ' + chave);
  const arq = planilhas.find(pl => pl.chave === chave);
  if (!arq) throw new Error('ainda nao recebi o arquivo "' + chave + '" (' + (FIN_ARQUIVOS_MANUAL[chave] || chave) + '). Me manda ele aqui no WhatsApp que eu registro e lanço na hora.');
  if (arq.editavel === false) throw new Error('arquivo somente leitura (espelho antigo): ' + chave);
  const escritas = Array.isArray(plano.escritas) ? plano.escritas : [];
  if (!escritas.length) throw new Error('plano sem escritas');
  if (escritas.length > 40) throw new Error('plano grande demais (' + escritas.length + ' escritas)');
  for (const e of escritas) {
    const z = cfg.abas[e.aba];
    if (!z) throw new Error('aba desconhecida: ' + e.aba);
    if (!z.escrita.length) throw new Error('aba somente leitura: ' + e.aba);
    if (!refDentro(z.escrita, e.ref)) throw new Error('celula fora da area de entrada: ' + e.aba + '!' + e.ref);
    if (!['numero','texto','data'].includes(e.tipo)) throw new Error('tipo invalido em ' + e.ref + ': ' + e.tipo);
  }
  // dry-run real (agrupa por aba) - lanca erro se bater em formula
  let buf = Buffer.from(arq.arquivo_b64, 'base64');
  const porAba = {};
  for (const e of escritas) { (porAba[e.aba] = porAba[e.aba] || []).push({ ref: e.ref, valor: e.valor, tipo: e.tipo }); }
  for (const aba of Object.keys(porAba)) buf = patchCelulas(buf, aba, porAba[aba]);
  return { buf, porAba, arq };
}

const ped = $('Preparar Fin').first().json;
const planilhas = $('Carregar Planilhas Fin').all().map(i => i.json).filter(p => p && p.arquivo_b64);
const pendentes = $('Carregar Pendente Fin').all().map(i => i.json).filter(p => p && p.id);
const esc = s => String(s == null ? '' : s).replace(/'/g, "''");
const comMemoria = (sql, dono, texto) => sql + "\nINSERT INTO giulia_memoria (role, content, from_numero) VALUES ('assistant', '" + esc(texto) + "', '" + esc(dono) + "');";

let pend = null;
if (ped.pendente_id) pend = pendentes.find(p => String(p.id) === String(ped.pendente_id));
else pend = pendentes[0] || null; // mais recente (ORDER BY id DESC)

if (!pend) {
  { const tx = 'Nao achei lancamento aguardando confirmacao. Me manda o lancamento de novo que eu monto na hora.'; return [{ json: { dono: ped.dono, enviar_texto: tx, sql: comMemoria('SELECT 1;', ped.dono, tx), enviar_arquivo: false } }]; }
}
const plano = typeof pend.plano === 'string' ? JSON.parse(pend.plano) : pend.plano;

try {
  const { buf, arq } = validarPlano(plano, planilhas); // revalida + aplica (dry-run = patch real aqui)
  const novoB64 = buf.toString('base64');
  const listaEscritas = plano.escritas.map(e => '  • ' + e.aba + '!' + e.ref + ' = ' + e.valor).join('\n');
  const sql =
    "INSERT INTO giulia_planilhas_fin_versoes (planilha_id, versao, arquivo_b64, resumo_mudanca) VALUES (" + parseInt(arq.id, 10) + ", " + parseInt(arq.versao, 10) + ", '" + esc(arq.arquivo_b64) + "', '" + esc(plano.resumo).substring(0, 500) + "');\n" +
    "UPDATE giulia_planilhas_fin SET arquivo_b64 = '" + esc(novoB64) + "', versao = versao + 1, atualizado_em = NOW() WHERE id = " + parseInt(arq.id, 10) + ";\n" +
    "UPDATE giulia_fin_pendentes SET status = 'aplicado', resolvido_em = NOW() WHERE id = " + parseInt(pend.id, 10) + ";";
  const enviar_texto = 'Lançado ✅\n' + listaEscritas + (arq.defasada ? '\n\n⚠️ Lancei na copia de ' + String(arq.atualizado_em || '').substring(0, 10) + ' - se voce editou a planilha por fora depois disso, me manda a versao nova pra eu nao perder teus ajustes.' : '') + '\n\nGuardei backup da versão anterior (v' + arq.versao + '). Os totais recalculam quando abrir o Excel. Te mando o arquivo atualizado.';
  return [{ json: { dono: ped.dono, enviar_texto, sql: comMemoria(sql, ped.dono, enviar_texto), enviar_arquivo: true, arquivo_b64: novoB64, nome_arquivo: arq.nome_arquivo } }];
} catch (e) {
  const sqlCancela = "UPDATE giulia_fin_pendentes SET status = 'cancelado', resolvido_em = NOW() WHERE id = " + parseInt(pend.id, 10) + ";";
  { const tx = 'Na hora de aplicar, o lancamento nao passou na validacao final: ' + e.message + '. NAO mexi na planilha. Me manda de novo que eu remonto.'; return [{ json: { dono: ped.dono, enviar_texto: tx, sql: comMemoria(sqlCancela, ped.dono, tx), enviar_arquivo: false } }]; }
}

